// Assume Polygon2d is std::vector<Point2d>
// Assume PolygonWithHoles2d is a wrapper for CGAL::Polygon_with_holes_2<Kernel>

std::vector<PolygonWithHoles2d> union2D(const Polygon2d& P1, const Polygon2d& P2) {
    // Convert input polygons to CGAL polygons
    Polygon_2 cgalP1, cgalP2;
    for (const auto& point : P1) {
        cgalP1.push_back(Point_2(point.x(), point.y()));
    }
    for (const auto& point : P2) {
        cgalP2.push_back(Point_2(point.x(), point.y()));
    }

    // Compute union
